//! The script Gravity Forms prints after an ajax form's hidden iframe: it moves the postback into the page.

const TEMPLATE: &str = r###"<script type="text/javascript">
/* <![CDATA[ */
 gform.initializeOnLoaded( function() {jQuery('#gform_ajax_frame_{ID}').on('load',function(){var contents = jQuery(this).contents().find('*').html();var is_postback = contents.indexOf('GF_AJAX_POSTBACK') >= 0;if(!is_postback){return;}var form_content = jQuery(this).contents().find('#gform_wrapper_{ID}');var is_confirmation = jQuery(this).contents().find('#gform_confirmation_wrapper_{ID}').length > 0;var is_redirect = contents.indexOf('gformRedirect(){') >= 0;var is_form = form_content.length > 0 && ! is_redirect && ! is_confirmation;var mt = parseInt(jQuery('html').css('margin-top'), 10) + parseInt(jQuery('body').css('margin-top'), 10) + 100;if(is_form){jQuery('#gform_wrapper_{ID}').html(form_content.html());if(form_content.hasClass('gform_validation_error')){jQuery('#gform_wrapper_{ID}').addClass('gform_validation_error');} else {jQuery('#gform_wrapper_{ID}').removeClass('gform_validation_error');}setTimeout( function() { /* delay the scroll by 50 milliseconds to fix a bug in chrome */ jQuery(document).scrollTop(jQuery('#gform_wrapper_{ID}').offset().top - mt); }, 50 );var current_page = jQuery('#gform_source_page_number_{ID}').val();jQuery(document).trigger('gform_page_loaded', [{ID}, current_page]);window['gf_submitting_{ID}'] = false;}else if(!is_redirect){var confirmation_content = jQuery(this).contents().find('.GF_AJAX_POSTBACK').html();if(!confirmation_content){confirmation_content = contents;}jQuery('#gform_wrapper_{ID}').replaceWith(confirmation_content);jQuery(document).scrollTop(jQuery('#gf_{ID}').offset().top - mt);jQuery(document).trigger('gform_confirmation_loaded', [{ID}]);window['gf_submitting_{ID}'] = false;wp.a11y.speak(jQuery('#gform_confirmation_message_{ID}').text());}else{jQuery('#gform_{ID}').append(contents);if(window['gformRedirect']) {gformRedirect();}}jQuery(document).trigger("gform_pre_post_render", [{ formId: "{ID}", currentPage: "current_page", abort: function() { this.preventDefault(); } }]);        if (event && event.defaultPrevented) {                return;        }        const gformWrapperDiv = document.getElementById( "gform_wrapper_{ID}" );        if ( gformWrapperDiv ) {            const visibilitySpan = document.createElement( "span" );            visibilitySpan.id = "gform_visibility_test_{ID}";            gformWrapperDiv.insertAdjacentElement( "afterend", visibilitySpan );        }        const visibilityTestDiv = document.getElementById( "gform_visibility_test_{ID}" );        let postRenderFired = false;        function triggerPostRender() {            if ( postRenderFired ) {                return;            }            postRenderFired = true;            gform.core.triggerPostRenderEvents( {ID}, current_page );            if ( visibilityTestDiv ) {                visibilityTestDiv.parentNode.removeChild( visibilityTestDiv );            }        }        function debounce( func, wait, immediate ) {            var timeout;            return function() {                var context = this, args = arguments;                var later = function() {                    timeout = null;                    if ( !immediate ) func.apply( context, args );                };                var callNow = immediate && !timeout;                clearTimeout( timeout );                timeout = setTimeout( later, wait );                if ( callNow ) func.apply( context, args );            };        }        const debouncedTriggerPostRender = debounce( function() {            triggerPostRender();        }, 200 );        if ( visibilityTestDiv && visibilityTestDiv.offsetParent === null ) {            const observer = new MutationObserver( ( mutations ) => {                mutations.forEach( ( mutation ) => {                    if ( mutation.type === 'attributes' && visibilityTestDiv.offsetParent !== null ) {                        debouncedTriggerPostRender();                        observer.disconnect();                    }                });            });            observer.observe( document.body, {                attributes: true,                childList: false,                subtree: true,                attributeFilter: [ 'style', 'class' ],            });        } else {            triggerPostRender();        }    } );} ); 
/* ]]> */
</script>"###;

pub fn script(form_id: i64) -> String {
    TEMPLATE.replace("{ID}", &form_id.to_string())
}
